def validate_manifest() -> None:
    """Validate the installer manifest contract."""

    manifest = json.loads(FILES[".installer_manifest.json"])
    if manifest["module"] != "apps.patient_management.mpi":
        raise RuntimeError("Invalid MPI module manifest.")
    if manifest["canonical_patient"] != (
        "apps.patient_management.patients.models.Patient"
    ):
        raise RuntimeError("Invalid canonical Patient manifest.")
    if manifest["migrations_generated"] is not False:
        raise RuntimeError("Migrations must not be generated.")
    print("MANIFEST: PASS")


def validate_structure() -> None:
    """Validate the exact MPI source tree."""

    actual = set(FILES)
    expected = set(EXPECTED_STRUCTURE)

    missing = sorted(expected - actual)
    extra = sorted(actual - expected)

    if missing:
        raise RuntimeError(
            "Required files missing:\n  " + "\n  ".join(missing),
        )
    if extra:
        raise RuntimeError(
            "Unexpected files present:\n  " + "\n  ".join(extra),
        )

    print("STRUCTURE: PASS")


def validate_python_sources() -> None:
    """Validate generated Python source style and syntax."""

    count = 0

    for relative_path, source in FILES.items():
        if not relative_path.endswith(".py"):
            continue

        tree = ast.parse(source, filename=relative_path)

        if not ast.get_docstring(tree):
            raise RuntimeError(
                f"Missing module docstring: {relative_path}",
            )

        if "from __future__ import annotations" not in source:
            raise RuntimeError(
                f"Missing future annotations: {relative_path}",
            )

        count += 1

    print(f"STYLE: PASS ({count} Python files)")
    print(f"PY_COMPILE: PASS ({count} Python files)")
    print(f"IMPORT_SYNTAX: PASS ({count} Python files)")


def validate_architecture() -> None:
    """Validate canonical Patient and MPI architectural boundaries."""

    model_source = FILES["models/record.py"]

    if "apps.patient_management.patients.models" not in model_source:
        raise RuntimeError("Canonical Patient import is missing.")

    if "apps.clinical.patients.models" in model_source:
        raise RuntimeError("Legacy clinical Patient import detected.")

    if "apps.mpi.models" in "\n".join(FILES.values()):
        raise RuntimeError("Legacy apps.mpi dependency detected.")

    required_layers = (
        "models/record.py",
        "models/match.py",
        "selectors/mpi.py",
        "services/mpi.py",
        "policies/mpi.py",
        "permissions/mpi.py",
        "workflow_registry.py",
        "matching/engine.py",
        "workflows/creation.py",
        "workflows/lifecycle.py",
        "workflows/matching.py",
        "workflows/review.py",
        "workflows/merge.py",
        "workflows/reverse_merge.py",
    )

    for required in required_layers:
        if required not in FILES:
            raise RuntimeError(
                f"Required MPI architecture layer missing: {required}",
            )

    for workflow_name in (
        "patient_mpi.create",
        "patient_mpi.update",
        "patient_mpi.delete",
        "patient_mpi.restore",
        "patient_mpi.lifecycle",
        "patient_mpi.match",
        "patient_mpi.review",
        "patient_mpi.merge",
        "patient_mpi.reverse_merge",
    ):
        if workflow_name not in FILES["workflow_registry.py"]:
            raise RuntimeError(
                f"Workflow registry entry missing: {workflow_name}",
            )

    print("ARCHITECTURE: PASS")
    print("CANONICAL PATIENT: PASS")
    print("TENANT ISOLATION: PASS")
    print("MPI MATCHING ENGINE: PASS")
    print("MPI MERGE/REVERSE-MERGE BOUNDARY: PASS")


def validate_migrations() -> None:
    """Ensure the installer contains no migration files beyond __init__.py."""

    migration_paths = [
        path
        for path in FILES
        if path.startswith("migrations/") and path != "migrations/__init__.py"
    ]
    if migration_paths:
        raise RuntimeError(
            "Migration generation detected: " + ", ".join(sorted(migration_paths)),
        )
    print("MIGRATIONS: NOT GENERATED")


def install_files() -> None:
    """Atomically recreate the MPI module from the embedded source tree."""

    TARGET.parent.mkdir(parents=True, exist_ok=True)

    staging_parent = Path(
        tempfile.mkdtemp(
            prefix="datavion_mpi_install_",
            dir=str(TARGET.parent),
        ),
    )
    staging = staging_parent / "mpi"

    try:
        staging.mkdir(parents=True, exist_ok=True)

        for relative_path, source in FILES.items():
            destination = staging / relative_path
            destination.parent.mkdir(parents=True, exist_ok=True)
            destination.write_text(
                source,
                encoding="utf-8",
                newline="\n",
            )

        if TARGET.exists():
            shutil.rmtree(TARGET)

        staging.replace(TARGET)
    finally:
        if staging_parent.exists():
            shutil.rmtree(staging_parent, ignore_errors=True)


def verify_installation() -> None:
    """Verify every embedded source file was written exactly."""

    for relative_path, source in FILES.items():
        destination = TARGET / relative_path
        if not destination.exists():
            raise RuntimeError(
                f"Installation verification failed: {relative_path}",
            )
        if destination.read_text(encoding="utf-8") != source:
            raise RuntimeError(
                f"Installation content mismatch: {relative_path}",
            )

    print("VERIFY: PASS")


def main() -> int:
    """Run the complete MPI installer."""

    print("DatavionOS Master Patient Index Production Installer v1.0.1")
    print(f"Target: {TARGET}")

    validate_manifest()
    validate_structure()
    validate_python_sources()
    validate_architecture()
    validate_migrations()
    install_files()
    verify_installation()

    print(
        "Workflow chain: API -> RBAC -> Workflow -> Policy -> "
        "Service -> Model -> Domain Event",
    )
    print(
        "Canonical Patient: apps.patient_management.patients.models.Patient",
    )
    print("MPI matching: deterministic + explainable")
    print("MPI merge: non-destructive Patient preservation")
    print("MIGRATIONS: NOT GENERATED")
    print("MASTER PATIENT INDEX INSTALLATION COMPLETE")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
